<template>
  <div class="page">
    <transition name="fade">
      <div class="title" v-if="showText">服飾專區</div>
    </transition>
    <div class="container">
      <transition name="slide">
        <div class="options-frame" v-if="showElement">
          <div v-for="(opt, index) in OptionsData" :key="index">
            <div
              class="option"
              @click="ClickOption(opt)"
              :class="{ active: opt.click }"
            >
              {{ opt.name }}
            </div>
          </div>
        </div>
      </transition>
      <transition name="fade">
        <div class="no-item" v-if="showNone">這裡是空的!</div>
      </transition>
      <transition name="slide">
        <div class="cloth-box-frame" v-if="showElement">
          <div
            class="cloth-frame"
            v-for="(cloth, index) in filteredList"
            :key="index"
            @click="ClickCloth(cloth)"
          >
            <img :src="cloth.image" />
            <div class="cloth-info-frame">
              <div class="cloth-name">{{ cloth.name }}</div>
              <div class="cloth-size">{{ cloth.size }}</div>
            </div>
          </div>
        </div>
      </transition>
    </div>
  </div>

  <i
    class="fa-regular fa-circle-question"
    id="help-btn"
    @click="showClothAllSitemap = true"
  ></i>

  <transition name="fade">
    <div class="add-btn" @click="CheckLogin" v-if="showElement">+</div>
  </transition>

  <div class="overlay" v-show="showElePage" @click="showElePage = false"></div>
  <transition name="slide-ele">
    <CheckClothInfo class="ele-page" v-show="showElePage" />
  </transition>

  <div
    class="overlay"
    v-show="clothStore.showElePage"
    @click="clothStore.showElePage = false"
  ></div>
  <transition name="slide-ele">
    <UploadCloth class="ele-page" v-show="clothStore.showElePage" />
  </transition>

  <div
    class="chat-overlay"
    v-show="chatStore.showElePage"
    @click="chatStore.showElePage = false"
  ></div>
  <transition name="slide-ele-right">
    <ChatEle class="chat-page" v-show="chatStore.showElePage" />
  </transition>

  <div
    class="overlay"
    v-if="showClothDetailSitemap"
    @click="showClothDetailSitemap = false"
  ></div>
