    X
  </div>
  <transition name="slide-sitemap">
    <ClothAllSitemap class="ele-page" v-if="showClothAllSitemap" />
  </transition>
</template>

<script>
import { ref, onMounted } from "vue";
import { useRouter } from "vue-router";

import { clothUiStore } from "@/store/cloth";
import { chatUiStore } from "@/store/chat";
import { loginUiStore } from "@/store/login";
import { errorUiStore } from "@/store/error";

import OptionsDataRaw from "@/assets/data/optionsData.json";

import CheckClothInfo from "./pageElement/CheckClothInfo.vue";
import UploadCloth from "./pageElement/UploadCloth.vue";
import ChatEle from "./pageElement/ChatEle.vue";
import ClothDetailSiteMap from "./sitemap/ClothDetailSiteMap.vue";
import ClothStoreSitemap from "./sitemap/ClothStoreSitemap.vue";
import ClothAllSitemap from "./sitemap/ClothAllSitemap.vue";

import { showMobileMenu } from "@/App.vue";

export const selectedCloth = ref({});
export const showElePage = ref(false);

export default {
  name: "ClothPage",
  components: {
    CheckClothInfo,
    UploadCloth,
    ChatEle,
    ClothDetailSiteMap,
    ClothStoreSitemap,
    ClothAllSitemap,
  },
  setup() {
    const showText = ref(false);
    const showElement = ref(false);
    const showClothDetailSitemap = ref(false);
    const showClothStoreSitemap = ref(false);
    const showClothAllSitemap = ref(false);

    const dataList = ref([]);
    const filteredList = ref([]);
    const showNone = ref(false);

    const clothStore = clothUiStore();
    const chatStore = chatUiStore();
    const loginStore = loginUiStore();
    const errorStore = errorUiStore();

    const router = useRouter();

    const OptionsData = ref(OptionsDataRaw); // 修正成 reactive 狀態

    const GetClothData = async () => {
      const response = await fetch("/data/clothData.json");
      const data = await response.json();

      dataList.value = data.filter((item) => {
        return !item.lock;
      });
    };

    const ClickOption = (opt) => {
      filteredList.value = dataList.value.filter((data) => {
        return data.category === opt.label;
      });

      opt.click = true;

      OptionsData.value.forEach((data) => {
        if (data.label !== opt.label) {
          data.click = false;
        }
      });

      if (opt.label === "all") {
        filteredList.value = dataList.value;
        opt.click = true;

        OptionsData.value.forEach((data) => {
          if (data.label !== "all") {
            data.click = false;
          }
        });
      }

      if (filteredList.value.length === 0) {
        showNone.value = true;
      } else {
        showNone.value = false;
      }
    };

    const ClickCloth = (cloth) => {
      selectedCloth.value = cloth;
      showElePage.value = true;
    };

    const CheckLogin = () => {
      if (loginStore.isAuthenticated) {
        clothStore.showElePage = true;
      } else {
        errorStore.LoadError("請先登入!");

        router.push("/login");
      }
    };

    onMounted(async () => {
      showText.value = true;
      showElement.value = true;
      showMobileMenu.value = false;
      // showClothDetailSitemap.value = true;

      // const clothStoreState = localStorage.getItem("ClothStoreSitemap");
      // if (clothStoreState === "true") {
      //   showClothStoreSitemap.value = true;

      //   localStorage.setItem("ClothStoreSitemap", "false");
      // }

      await GetClothData();

      filteredList.value = dataList.value;

      if (filteredList.value.length === 0) {
        showNone.value = true;
      }

      OptionsData.value.forEach((data) => {
        if (data.label === "all") {
          data.click = true;
        }
      });
    });

    return {
      showMobileMenu,
      showElePage,
      showText,
      showElement,
      showClothDetailSitemap,
      showClothStoreSitemap,
      showClothAllSitemap,
      dataList,
      filteredList,
      showNone,
      clothStore,
      chatStore,
      OptionsData,
      GetClothData,
      ClickOption,
      ClickCloth,
      CheckLogin,
    };
  },
};
</script>

